async () => {
const n=(window.gameState.notes||[]); return { salvageNotes: JSON.stringify(n).split('catalogue_salvage_line').length-1, noteTitles: n.map(x=>x.title||x.id).join('|'), toast: [...document.querySelectorAll('body *')].filter(e=>e.children.length<6 && (e.textContent||'').includes('First box is in') && e.offsetParent!==null).length, g: ['flag1_submitted','flag1_read_heard','flag1_texted'].map(k=>k+'='+window.gameState.globalVariables[k]).join(' ') };

}

